import{_ as o,o as a,c,a5 as d}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"二、搭建服务注册中心","description":"","frontmatter":{"title":"二、搭建服务注册中心","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/二、搭建服务注册中心.md","filePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/二、搭建服务注册中心.md"}'),t={name:"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/二、搭建服务注册中心.md"};function l(i,e,p,r,s,n){return a(),c("div",null,[...e[0]||(e[0]=[d('<div><p>微服务架构下，我们将项目按照功能或者业务拆分为若干个小的服务，那么这些服务应该如何进行管理？ 这就需要一个服务注册中心，可以把它理解为一个管理员，我们将所有的服务注册到这个管理员，由它去进行维护和管理。</p><p>注册到注册中心的每一个服务，都会有一个服务名称，如果出现了相同的服务名称，则认为是两个相同的服务，那么当客户端在调用这些服务的时候，会自动以负载均衡的方式去调用，将压力分担到不同的服务上，功能上类似于<code>Nginx</code>。此外，注册中心和注册中心之间也可以相互注册，达到高可用的服务集群效果。</p><p>服务注册中心有很多种，<code>Dubbo</code>，<code>Eureka</code>，<code>Nacos</code>……，本篇文章采用较简单的<code>Eureka</code>来搭建注册中心，在以后的博文中会陆续介绍其他的几个注册中心。</p><p>首先，选中<code>micro</code>文件夹，右键，<code>new</code>，<code>module</code>：</p><p>这里的意思是，表明这个子项目是一个注册中心</p><p>点击<code>create</code>。</p><p>然后我们对服务注册中心做一下配置； 注册中心在启动时，会寻找另一个注册中心进行注册，但是因为我们这是单机项目，不是集群式的，没必要搭建其他注册中心，所以我们要让这个注册中心扛起大旗，独立起来，做一个成熟的注册中心。也就是说，我们要禁止它注册它自己（另外，我把配置文件的格式改成<code>.yml</code>了）： <code>#</code> 端口号为<code>8080</code>（默认也是<code>8080</code>）</p><ul><li>server:</li><li>port: 8080</li><li><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>禁止注册自己</p><ul><li>eureka:</li><li>client:</li><li>register-with-eureka: false</li><li>fetch-registry: false</li></ul><p>然后我们在启动类上加<code>@EnableEurekaServer</code>注解，表示将这个项目作为 服务注册中心：</p><p>然后我们启动项目（注意<code>application.yml</code>文件的编码格式需要是<code>UTF-8</code>）： 另外，这里可能有坑，如果你出现了以下错误： <code>Caused by: java.nio.charset.MalformedInputException: Input length = 1</code> 说明你的<code>application.yml</code>文件的编码格式不是<code>UTF-8</code>！！！解决办法： 然后把<code>application.yml</code>文件删了，重新创建，内容复制一遍……我也没找到什么更好的办法。。。</p><p>我们打开浏览器，访问<code>8080</code>，可以看到以下页面，说明注册中心已经启动成功了，只不过没有任何服务注册进来：</p></div>',1)])])}const m=o(t,[["render",l]]);export{u as __pageData,m as default};
